/* @component: video-gallery-slider */
(function () {
  const libs = {
    swiper: {
      js: 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.js',
      css: 'https://cdn.jsdelivr.net/npm/swiper@11/swiper-bundle.min.css'
    },
    plyr: {
      js: 'https://cdn.plyr.io/3.7.8/plyr.js',
      css: 'https://cdn.plyr.io/3.7.8/plyr.css'
    }
  };
  function loadLib(id, js, css, cb) {
    let s = document.getElementById(id);
    if (!s) {
      const l = document.createElement('link');
      l.rel = 'stylesheet';
      l.href = css;
      document.head.appendChild(l);
      s = document.createElement('script');
      s.id = id;
      s.src = js;
      s.onload = cb;
      document.head.appendChild(s);
    } else if (s.dataset.loaded === 'true' || (id.indexOf('swiper') !== -1 && typeof Swiper !== 'undefined') || (id.indexOf('plyr') !== -1 && typeof Plyr !== 'undefined')) {
      cb();
    } else {
      s.addEventListener('load', cb);
    }
  }
  function initSliderFull() {
    document.querySelectorAll('.slider-full').forEach(function (container) {
      if (container.dataset.initialized === 'true') return;
      container.dataset.initialized = 'true';
      const swiperNode = container.querySelector('.sliderFull');
      if (!swiperNode) return;
      new Swiper(swiperNode, {
        slidesPerView: 1,
        spaceBetween: 20,
        loop: true,
        observer: true,
        observeParents: true,
        pagination: {
          el: container.querySelector('.swiper-pagination'),
          clickable: true
        },
        navigation: {
          nextEl: container.querySelector('.swiper-button-next'),
          prevEl: container.querySelector('.swiper-button-prev')
        },
        breakpoints: {
          768: { slidesPerView: 2 },
          1200: { slidesPerView: 3 }
        }
      });
      setTimeout(function () {
        const videos = container.querySelectorAll('.slide-player');
        videos.forEach(function (v) {
          if (v && !v.plyr && !v.closest('.plyr')) {
            new Plyr(v, {
              autoplay: false,
              controls: ['play-large', 'play', 'progress', 'current-time', 'mute', 'volume', 'fullscreen']
            });
          }
        });
      }, 500);
    });
  }
  loadLib('swiper-full-v11', libs.swiper.js, libs.swiper.css, function () {
    loadLib('plyr-full-v3', libs.plyr.js, libs.plyr.css, function () {
      if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', initSliderFull);
      } else {
        initSliderFull();
      }
      setTimeout(initSliderFull, 300);
    });
  });
})();
/* @end: video-gallery-slider */
